"""Curated source registry for Signal Wire.

Ratings are editorial reliability bands, not claims that every report is correct:
5 = primary/official record or direct filing; 4 = established reporting/data venue;
3 = specialist venue useful for discovery; 2 = commentary/aggregator; 1 = lead only.
The collector should only poll sources with a configured public feed/API.
"""
from __future__ import annotations

def _rows(names, category, tier, rating, rationale, base=None):
    out=[]
    for name,url in names:
        host=url.split('/')[2].removeprefix('www.')
        out.append({'name':name,'url':url,'domain':host,'category':category,'tier':tier,'rating':rating,'stars':'★'*rating+'☆'*(5-rating),'rationale':rationale,'monitorable':False})
    return out

