def build_registry():
 rows=[]
 rows += _rows(OFFICIAL,'Macro / official','official',5,'Primary record, regulator, statistical agency, or direct official data.')
 rows += _rows(CRYPTO,'Crypto','specialist',4,'Protocol, developer, security, on-chain data, exchange disclosure, or specialist reporting; verify claims against primary records.')
 rows += _rows(AI,'AI & biotech','specialist',4,'Research lab, regulator, academic venue, company disclosure, or specialist reporting; distinguish preprint, trial, and approval.')
 rows += _rows(OTHER,'Cross-market discovery','discovery',3,'Useful context or lead generation; not treated as independent confirmation without corroboration.')
 # Prefer high-signal sources when duplicates exist; preserve the first occurrence.
 unique={r['domain']:r for r in rows}
 rows=list(unique.values())
 for r in rows:
  if r['name'] in {'TikTok research leads','X Research Leads','Reddit CryptoCurrency','Reddit Bitcoin','Bitcoin Talk'}:
   r.update(rating=1,stars='★☆☆☆☆',tier='discovery',rationale='Discovery lead only; identity, incentives, and sourcing require independent verification.')
  elif r['name'] in {'CryptoPanic','CoinMarketCap','CoinGecko','Trading Economics','Investing.com'}:
   r.update(rating=3,stars='★★★☆☆',rationale='Useful aggregator or market-data discovery; verify material claims at the original source.')
 # Keep the public registry intentionally focused: 200 reviewed sources with a crypto/AI emphasis.
 # Quotas prevent a large official directory from crowding out the requested specialist coverage.
 quotas={'Macro / official':52,'Crypto':77,'AI & biotech':51,'Cross-market discovery':20}
 chosen=[]
 for cat,limit in quotas.items():
  chosen.extend(sorted((r for r in rows if r['category']==cat),key=lambda r:(-r['rating'],r['name']))[:limit])
 return sorted(chosen,key=lambda r:(-r['rating'],r['category'],r['name']))
REGISTRY=build_registry()
REGISTRY_BY_DOMAIN={r['domain']:r for r in REGISTRY}

def source_meta(name,url):
 return REGISTRY_BY_DOMAIN.get(url.split('/')[2].removeprefix('www.'), {'name':name,'domain':url.split('/')[2],'url':url,'category':'Unrated','tier':'discovery','rating':1,'stars':'★☆☆☆☆','rationale':'Not yet reviewed; discovery only.','monitorable':True})
